SELECT l.user_id,l.entity_id,l.version,l.favorite,l.wrong,l.progress,l.updated_at,v.title FROM learning_record l JOIN content_version v ON v.entity_id=l.entity_id AND
    v.version=l.version WHERE l.user_id=#{id}
ORDER BY l.entity_idl.updated_at ASCDESC, l.entity_id ASC LIMIT #{query.size} OFFSET #{query.offset}
